// scripts/test-inventory.ts — the single source of test counts (guide 08 §5).
// Reads test-results/vitest.json and test-results/playwright.json (generated by
// `npm run test:coverage` and a Playwright run with a JSON reporter) and writes
// docs/evidence/test-inventory.json. Fails when required categories are empty.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execSync } from 'node:child_process';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// Spec categories that must never report zero PASSED tests (guide 08 §7
// minimums). Each maps to the vitest tag declared on the owning suites.
const REQUIRED: Record<string, string> = {
  authz: 'authz',
  authn: 'authn',
  'command-validation': 'command-validation',
  telemetry: 'telemetry',
  automation: 'automation',
  notification: 'notification',
  'rate-limit': 'rate-limit',
  retention: 'retention',
  realtime: 'realtime',
  'status-page': 'status-page',
  incident: 'incident',
  scheduler: 'scheduler',
  migration: 'migration',
  queue: 'queue',
  observability: 'observability',
  security: 'security',
};

type VitestReport = {
  numTotalTests: number;
  numPassedTests: number;
  numFailedTests: number;
  testResults?: {
    name: string;
    status: string;
    assertionResults?: {
      name: string;
      fullName: string;
      status: string;
      tags?: string[];
    }[];
  }[];
};

type PlaywrightReport = {
  stats?: { expected: number; skipped: number };
  suites?: unknown;
};

function readJson<T>(p: string): T | null {
  if (!existsSync(p)) return null;
  try {
    return JSON.parse(readFileSync(p, 'utf8')) as T;
  } catch {
    return null;
  }
}

function main(): void {
  const vitest = readJson<VitestReport>(path.join(root, 'test-results', 'vitest.json'));
  const pw = readJson<PlaywrightReport>(path.join(root, 'test-results', 'playwright.json'));

  // R2-47: count PASSED tests by their declared tags (guide 08 §5), not
  // filename substrings, and never count failed/skipped files or tests.
  const categories: Record<string, number> = {};
  const byTag: Record<string, number> = {};
  if (vitest?.testResults) {
    for (const r of vitest.testResults) {
      if (r.status !== 'passed') continue;
      for (const a of r.assertionResults ?? []) {
        if (a.status !== 'passed') continue;
        for (const tag of a.tags ?? []) {
          byTag[tag] = (byTag[tag] ?? 0) + 1;
        }
      }
    }
    for (const [cat, tag] of Object.entries(REQUIRED)) {
      categories[cat] = byTag[tag] ?? 0;
    }
  }

  const inventory = {
    commit: (() => {
      try {
        return execSync('git rev-parse HEAD', { cwd: root, encoding: 'utf8' }).trim();
      } catch {
        return 'unknown';
      }
    })(),
    vitest: {
      total: vitest?.numTotalTests ?? 0,
      passed: vitest?.numPassedTests ?? 0,
      failed: vitest?.numFailedTests ?? 0,
    },
    playwright: { total: pw?.stats?.expected ?? 0, skipped: pw?.stats?.skipped ?? 0 },
    byTag,
    categories,
    generatedAt: new Date().toISOString(),
  };

  const outDir = path.join(root, 'docs', 'evidence');
  mkdirSync(outDir, { recursive: true });
  writeFileSync(path.join(outDir, 'test-inventory.json'), JSON.stringify(inventory, null, 2));

  if (vitest) {
    const missing = Object.keys(REQUIRED).filter((c) => !categories[c]);
    if (missing.length > 0) {
      console.error(
        `test-inventory: no test file matched required categories: ${missing.join(', ')}`,
      );
      process.exit(1);
    }
  } else {
    console.warn(
      'test-inventory: test-results/vitest.json missing — run `npm run test:coverage` first.',
    );
  }

  if (pw) {
    const stats = (pw.stats ?? {}) as {
      expected?: number;
      skipped?: number;
      unexpected?: number;
    };
    // R1: skips and failures are inventory failures, not silent gaps.
    if ((stats.unexpected ?? 0) > 0) {
      console.error(`test-inventory: ${stats.unexpected} Playwright test(s) failed.`);
      process.exit(1);
    }
    if ((stats.skipped ?? 0) > 0) {
      console.error(
        `test-inventory: ${stats.skipped} Playwright test(s) skipped — nothing may be skipped in CI.`,
      );
      process.exit(1);
    }
  }
  console.log('test-inventory written to docs/evidence/test-inventory.json');
}

main();
